import{_ as a,a as r}from"./chunks/6dc0f25651546a02c76f.B6jtVJ8h.js";import{_ as o,C as l,o as i,c as n,j as e,a as s,E as m,a6 as h}from"./chunks/framework.CnPv4DE1.js";const q=JSON.parse('{"title":"2024年如何作为内容创作者赚钱（构建-教学-赚钱法）","description":"","frontmatter":{"title":"2024年如何作为内容创作者赚钱（构建-教学-赚钱法）","originalTitle":"How To Make Money As A Content Creator In 2024 (The Build Teach Earn Method)","date":"2023-11-25","originalUrl":"https://thedankoe.com/letters/how-smart-creators-make-money-the-build-teach-earn-method/","minutes":17,"sourceHash":"c9bf7d0b52297a2bdf3a925108a335b554e5fa32d1d8b2dab83c1c02583e7c59","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/how-smart-creators-make-money-the-build-teach-earn-method/"}]]},"headers":[],"relativePath":"letters/how-smart-creators-make-money-the-build-teach-earn-method.md","filePath":"letters/how-smart-creators-make-money-the-build-teach-earn-method.md"}'),d={name:"letters/how-smart-creators-make-money-the-build-teach-earn-method.md"};function c(u,p,g,b,f,k){const t=l("ArticleMeta");return i(),n("div",null,[p[0]||(p[0]=e("h1",{id:"_2024年如何作为内容创作者赚钱-构建-教学-赚钱法",tabindex:"-1"},[s("2024年如何作为内容创作者赚钱（构建-教学-赚钱法） "),e("a",{class:"header-anchor",href:"#_2024年如何作为内容创作者赚钱-构建-教学-赚钱法","aria-label":'Permalink to "2024年如何作为内容创作者赚钱（构建-教学-赚钱法）"'},"​")],-1)),m(t),p[1]||(p[1]=h('<p><a href="https://www.youtube.com/embed/fY7B5ZermSw?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p><img src="'+a+'" alt=""></p><p><strong>每个人都想成为一名内容创作者 (content creator)。</strong></p><p>这不是件坏事。</p><p>尤其是如果你能预测未来工作的走向。</p><p>婴儿潮一代会告诉你去“找份正经工作”，而这些正经工作在几十年后将不复存在。</p><p>他们没有意识到，正是工业时代<em>创造了</em>这些工作。</p><p>他们同样没有意识到，信息时代已经<em>创造了</em>这些全新的、利润更丰厚的工作。</p><p>盈利能力决定了社会和经济的发展方向。</p><p>科技使得利润更高的工作领域成为可能。</p><p>创作者经济 (creator economy) 预计将在未来5年内规模翻倍，从2500亿美元增长到4800亿美元。</p><p>最大的问题在于缺乏理解。</p><p>人们没有从大局观的角度理解内容创作到底是什么。</p><p>每个人都感到被吸引去成为内容创作者，这是有原因的。</p><p>因为这是人类的天性。</p><p>因为人们想做自己想做的事。</p><p>因为人们有一种天生的内驱力去追求自己的好奇心，成为价值的载体，并用自己的双手去创造。你知道的，就是那些被学校和工作从你身上剥夺的东西。</p><p>因为当你剥开表象，这正是人类自然进化一直以来所指向的方向。</p><p>自人类诞生以来，我们一直用技术解决问题，以摆脱机械且耗时的体力劳动，从而追求自我实现 (self-actualization) 和超越。</p><p>让我们来定义一下什么是“内容”，什么是“创作”。</p><p><strong>内容：</strong></p><p><em>被容纳或包含在某物中的东西。</em></p><p>换句话说，万物皆是内容。</p><p>内容是结构化的信息。</p><p>信息是我们作为一个物种学习、成长和适应的方式。信息占据了我们的头脑，塑造了我们的头脑，并从我们的头脑中产出。我们利用自己心灵的结构来创造内容。</p><p>互联网的前端是内容。<br> 你头脑的前端是内容。<br> 互联网的后端是代码。<br> 你头脑的后端是代码。</p><p><strong>创作：</strong></p><p>使之存在（无中生有）。</p><p>这就是人类所做的事。</p><p>人类创造。人类解决问题。人类构建解决方案。这就是你的优势。</p><p>生而为人，就是去扩展、去超越、去创造。</p><p>成为机器人，则是忘记你拥有这份天赋，任由你的头脑在学校教育和雇佣关系中被他人的突发奇想所塑造。</p><p>追根溯源，内容创作只是在做一个人，而不是像那些过时的工作让你相信的那样去做一个机器人。</p><p>每个人都是内容创作者。只是有些人选择有意识地去做，并因此获得报酬，在一个叫做“互联网”的地方，那里没有物理边界来限制你的触达和潜力。</p><p>内容创作是让你写的东西和说的话变得更有价值的方式，因为你首先必须成为一个足够有价值的个体，才能像我们的祖先为当地的物理社区做贡献那样，为全球数字社区做出贡献（并从中获利）。</p><p><strong>在我们开始之前：</strong></p><p>Koe的黑五大促正在进行中。</p><p>我的课程和产品最高可享5折优惠。</p><p>我为你把所有东西都整理在了一个专属页面上。</p><p>如果你一直在等机会入手我的东西，现在正是时候。</p><p><a href="https://thedankoe.com/bfcm" target="_blank" rel="noreferrer">趁着我向这个毫无用处的节假日妥协，赶在周一午夜前薅我羊毛吧。</a></p><h2 id="内容创作不是一份工作或一门生意——它是一块磁铁" tabindex="-1">内容创作不是一份工作或一门生意——它是一块磁铁 <a class="header-anchor" href="#内容创作不是一份工作或一门生意——它是一块磁铁" aria-label="Permalink to &quot;内容创作不是一份工作或一门生意——它是一块磁铁&quot;">​</a></h2><p>让我们把话题拉回现实（即使这没那么有趣，也少了几分兴致）。</p><p>在商业中，你需要两样东西才能赚钱：</p><ol><li><strong>人</strong> —— 商业就是价值交换，如果你想要钱，你需要<em>另一个人</em>把钱给你，以交换同等价值的东西。</li><li><strong>产品</strong> —— 产品（包括服务）是一个有价值的创造物，无论是实体的还是数字的，最好能解决某人生活中的实际问题。</li></ol><p>当然，这里面还有更多细节，比如你要懂得如何向你吸引来的人推销产品，但你绝对需要人和产品。这是必不可少的。</p><p>所以，这是我们需要明白的第一件事：</p><p><em>内容就是作为创作者的你，将人们吸引到你的产品上的方式。</em></p><p>你该如何创作吸引人的内容？</p><p>通过解构你的大脑，并将其中最精华的部分分享到互联网上。</p><p>大多数人在刚开始写作时都会很挣扎，因为他们会淡化自己要说的所有东西，或者试图把它搞得过于复杂。</p><p>以下就是写出吸引像你一样的人的内容所需的确切要素：</p><h3 id="_1-产生共鸣的话题" tabindex="-1">1) 产生共鸣的话题 <a class="header-anchor" href="#_1-产生共鸣的话题" aria-label="Permalink to &quot;1) 产生共鸣的话题&quot;">​</a></h3><p>成为内容创作者仍然是一件新鲜事。</p><p>人们仍然在运用陈旧过时的商业和营销策略，希望能以此做大受众群体。</p><p>不断细分你谈论的话题 \u2028\u2028*“但是Dan，财富藏在细分领域 (niche) 里！！！这是个事实！”*</p><p>我懂，但人们误解了它的意思。</p><p>另外，如果我决定要建立一个庞大的受众群体，并<em>创造</em>一个细分领域呢？</p><p>如果赚到的钱一样多，我宁愿拥有300万粉丝，也不愿只有1万粉丝。</p><p>前者能给你带来海量的、看不见的杠杆 (leverage) 、灵活性和选择。</p><p>而后者可能只要流失3个客户，就会觉得生存岌岌可危。</p><p>所以，写作内容要宽泛，然后通过你的内容漏斗逐步收窄至你的专业领域。</p><p>你处于漏斗顶部的社交媒体账号，应包含人们正在积极搜索和研究的话题，如生产力、心理学、心态、自由职业、技能获取、商业、营销等。</p><p>人们是真的<em>想</em>关注和学习这些东西。</p><p>别搞什么疯狂的“电子商务商店自动响应机制”。</p><p>从你的社交媒体到通讯，再到播客来教育受众，让你的产品页面成为证明你权威性的最后拼图，然后在细分领域里想走多深就走多深。</p><p>这种策略将需要你拥有一系列从入门到进阶的产品。</p><p>如果你只打算出售一种极其特定且高客单价的服务，这不适合你。</p><h3 id="_2-极具冲击力的观点" tabindex="-1">2) 极具冲击力的观点 <a class="header-anchor" href="#_2-极具冲击力的观点" aria-label="Permalink to &quot;2) 极具冲击力的观点&quot;">​</a></h3><p>如果你不选边站队，你的帖子、句子、段落或写的任何东西都不会产生冲击。</p><p>如果你站在中间，人们可能会喜欢你，但你无法影响他们。</p><p>冲击力 = 写出极其有力量的文字，让这些文字免费长驻在他们的脑海里。即使他们的注意力已经离开了你的内容，它依然占据着他们的心智。他们会向朋友和同事讲述你的观点，因为他们想强化彼此共同的极端信念，以获得认同感。</p><p>当你全心全意地选边站队并表达自己的信念时，你写出的文字才会有冲击力。</p><p>什么是最好去表达的信念？</p><p>那些普通人会觉得“极端”或“疯狂”的信念。</p><p>我们不希望那些甘于平庸的人关注我们。</p><p>你的信念构成了你品牌的基础与认知。</p><p>经常谈论它们，并将它们作为在你的大部分内容中提供视角、经验和案例的方式。</p><p>你认为自由职业是初学者赚钱的最佳途径吗？</p><p>你认为纯素食主义者很蠢，人们应该多吃动物类食物吗？</p><p>你认为人们应该在凌晨3点起床并直接投入工作吗？</p><p>你的目标是做到90%的人喜欢，10%的人讨厌。</p><p>如果你不能在受众中保持这种两极分化（就像在一段蓬勃发展的亲密关系中那样），你就没有给人们留下任何在乎你的理由。</p><p>你需要这种推拉感。</p><p>这不是写作建议，这是精神层面的建议。</p><p>让你的文字保持原始、有力且易于消化。</p><p>删除并替换那些让你听起来缺乏自信的词语。</p><p>写得要有冲击力，但在回复中有别人提出更好视角时，也要对改变想法持开放态度。</p><p>拥有坚定的信念，但保持开放的心态。</p><h3 id="_3-新颖的视角" tabindex="-1">3) 新颖的视角 <a class="header-anchor" href="#_3-新颖的视角" aria-label="Permalink to &quot;3) 新颖的视角&quot;">​</a></h3><p>大多数人只是在反刍同样的观点。</p><p>他们从未提供看待事物的新方式。</p><p>新颖的视角是提供“良性”多巴胺刺激的主要方式，这种刺激有助于学习、理解和行动。</p><p>大多数创作者分发廉价的多巴胺，就像发糖果一样，希望能建立忠实的读者群。</p><p>你通过在未知中狩猎来创造新颖的视角。</p><p>你通过亲身经历（追求自己的目标和自我反思），以及在书籍、播客、文章和社交媒体账号的深处研究信息，在未知中进行狩猎。</p><p>人们不只想要又一个普通的观点，他们想要独特的视角。</p><p>就像这封信的开头。</p><p>我不得不停下来，思考我想传达的想法，并将亲身经历与塑造我世界观的哲学思想结合起来。</p><p>带着你随着时间推移获得的话题、信念和新颖视角，去精心打磨能吸引注意力的文字，而不使用令人反感的策略。</p><h3 id="_4-写作结构" tabindex="-1">4) 写作结构 <a class="header-anchor" href="#_4-写作结构" aria-label="Permalink to &quot;4) 写作结构&quot;">​</a></h3><p>你可以拥有世界上最伟大的点子，但你必须注意你把它们发布在什么地方。</p><p>当人们读一本书时，他们可以接受大段的文字。</p><p>当人们在社交媒体上时，他们需要在你的文字中被引导（否则他们就会直接滑走，看下一个吸引他们注意力的人）。</p><p><strong>使用换行。</strong></p><p>去看看我的任何一篇帖子，注意我是如何在句子之间增加换行以提高可读性的。</p><p><strong>研究表现优异的结构。</strong></p><p>观察热门的X（推特）帖子、IG帖子、YouTube标题和文章标题。</p><p><strong>多写清单。</strong></p><p>项目符号清单能开启一个好奇心回路。</p><p>人们可以基于你清单中的任何一点去点赞、分享、关注或评论。</p><p>清单会迫使你将每一项浓缩得极具冲击力。正因如此，人们会在评论中加入自己的想法或细微见解（从而增加触达率）。</p><p>任何东西都可以变成清单。</p><p>去搜寻一个想法，然后试着把它变成包含原因、好处、痛点或步骤的清单。\u2028\u2028一个小时后我需要发帖了，所以我得赶快找个想法。</p><p>好了，我回来了，这个想法是：来自Medium上一篇文章标题的“改变我生活的10个习惯”。</p><p>以下是我为X写的内容：</p><blockquote><p>如何清理你的头脑：\u2028&gt; \u2028&gt; 多散步。多阅读。多写作。多倾听。多举铁。多做战略。多去构建。\u2028&gt; \u2028&gt; 少刷手机。少放纵。少批评。少反刍。少久坐。少拖延。\u2028&gt; \u2028&gt; 清醒的头脑只留给那些不抗拒现实，而是参与现实的人。</p></blockquote><p>我本来可以把所有这些都列为项目符号，但如果我将其同步发布到所有平台，这就不适合排版了。</p><p>钩子 &gt; 正文 &gt; 结论。</p><h3 id="_5-曝光度与努力" tabindex="-1">5) 曝光度与努力 <a class="header-anchor" href="#_5-曝光度与努力" aria-label="Permalink to &quot;5) 曝光度与努力&quot;">​</a></h3><p>大多数创作者犯的一个巨大错误，就是去在意算法和最新趋势。</p><p>他们缺乏对算法底层逻辑的理解：人性、心理学和机制。</p><p>它们各自的原则：</p><ul><li>渴望的结果。</li><li>迫在眉睫的问题。</li><li>清晰的解决方案或系统。</li></ul><p>当你的内容能死死拿捏住这里面的每一点时，人们就会去分享。</p><p>如果他们不分享，那说明你没有自己想的那么会写。你需要在写作中进行更多的数据收集、测试和实验。</p><p>除此之外，创作者们意识到算法能让别人看到他们的内容从而获得增长，却没意识到他们自己可以控制看到其内容的人数。</p><p>你必须为自己的成长付出努力，特别是作为一个新手，你要去回复大账号（他们有受众能看到你的回复并关注你），与创作者建立联系以互帮互助，或者可能的话花钱寻求帮助。</p><p>我在<a href="/letters/how-to-actually-grow-on-social-media-what-they-dont-tell-you">如何在社交媒体上实现真正的增长（即使你0粉丝）</a>中详细拆解了所有这些内容。</p><h2 id="你需要一个你自己真正会购买和使用的产品" tabindex="-1">你需要一个你自己真正会购买和使用的产品 <a class="header-anchor" href="#你需要一个你自己真正会购买和使用的产品" aria-label="Permalink to &quot;你需要一个你自己真正会购买和使用的产品&quot;">​</a></h2><p><img src="'+r+'" alt=""></p><p>不要自欺欺人，去创造一个<em>你</em>自己真正会买、会用、并从中获益的产品。商业中没有多少捷径，但这就是其中之一。</p><p>当你自己就是那个细分领域时，你就不需要过度担心市场调研、产品市场契合度，或者去打造完美的营销策略。</p><p>积累受众是现代商业的作弊码。</p><p>你的内容就是你测试想法的方式，而这些想法将转化为你的营销素材。你早已知道这套行得通。</p><p>大约一年前，我在 X 上写了一篇长文（thread），拆解了我是如何撰写文章和时事通讯，并将其重新加工成适用于所有平台的内容的。</p><p>那篇长文反响非常好，所以我把它变成了我的<a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">2小时写手（2-Hour Writer）课程</a>。</p><p>因为你的受众已经接触了大量你的内容，他们对你更加信任。你不需要拥有完美的、以转化为中心的落地页和文案，因为人们早已决定好是否要购买。</p><p>随着时间的推移，你的内容已经提升了他们对自身问题的认知水平。你的产品落地页或销售页只是提供清晰度的临门一脚。</p><p>当我还是个依赖冷私信、冷邮件和客户推荐的自由职业者时，我对于写出转化率最优的网站文案感到极度神经质。</p><p>每次发邮件，我都觉得必须要榨干它的所有价值。</p><p>我毫无喘息的空间。</p><p>人们通常会告诉你两条路。</p><p>第一条是等到你的读者群体积累得足够庞大时再去变现。</p><p>第二条是立即变现。</p><p>第一种选择适合那些收入稳定且已经掌握一门技能的人。</p><p>第二种选择适合那些<em>利用</em>社交媒体作为<em>载体</em>，来创造独立收入来源并发展自身技能的人。</p><p>我已经听厌了人们说“先在社交媒体之外做个生意，然后再去积累受众并变现。”</p><p>不再藏着掖着了。</p><p>过去不是这样的，但现在，社交媒体是一种<em>启动</em>业务的可行方式。</p><p>事实上，它可能是你能走的最有效的路径。</p><p>如果你是个纯新手，请使用“构建-教学-赚钱法”：</p><h3 id="取得数字成功的构建-教学-赚钱法" tabindex="-1">取得数字成功的构建-教学-赚钱法 <a class="header-anchor" href="#取得数字成功的构建-教学-赚钱法" aria-label="Permalink to &quot;取得数字成功的构建-教学-赚钱法&quot;">​</a></h3><p>在成为创作者之前，我已经掌握了不少技能，并且有自由职业的经验。</p><p>这种方法帮助我以更快的速度取得了成功。</p><p>它融入了你作为创作者谋生所需的一切要素。</p><p><strong>1) 通过构建来学习高价值技能以赚取收入</strong></p><p>最好的学习方式是自我教育（让你拥有知识），同时构建一些有形的东西（让你拥有经验）。</p><p>很少有内容创作者意识到，如今的大多数生意本质上都是一样的。</p><p>它们都通过品牌、内容、产品和促销在线上获取客户。</p><p>这意味着：</p><p>如果你学会了让<em>你</em>的创作者业务取得成功的技能，你就可以运用这些技能，以自由职业服务或数字产品的形式为其他企业提供帮助。</p><p>构建创作者业务所需的每一项技能，<em>恰恰就是</em>每个人都在谈论的高价值技能。</p><p>在制作你的头像、横幅、网站图片、缩略图等时学习平面设计。</p><p>在构建你的落地页、网站、社交媒体内容和时事通讯时学习文案撰写和内容创作。</p><p>学习社交媒体运营（是的，这是一门技能），以此来建立你的粉丝群、人脉网和权威性。</p><p>在打造你的产品或服务时学习营销和销售。</p><p>在推广你的产品或服务以获取买家时学习广告和促销。</p><p>还有很多，但每一门生意（至少是我们关心的、未来能盈利的生意）都依赖于：</p><ul><li><strong>漏斗顶部</strong> —— X、Instagram、YouTube、LinkedIn 等社交媒体平台。</li><li><strong>漏斗中部</strong> —— 时事通讯、引流诱饵、私信以及任何其他培育读者的方式。</li><li><strong>漏斗底部</strong> —— 产品、服务、向上销售、向下销售等。</li></ul><p>我鼓励你慢慢地去学习每一项能提升你作为创作者成功率的技能。</p><p>从写作开始。</p><p>那是产生最多流量和粉丝的东西。</p><p>你可以通过练习我们上面或之前信件中讨论过的内容来提升自己，或者你也可以跳过试错阶段，直接购买<a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">2小时写手（2-Hour Writer）</a>。</p><p>当你有了流量和粉丝，你就可以真正地销售你的产品和服务。</p><p>或者，你可以向其他企业收取高价，因为他们的主要问题就是流量和潜在客户。</p><p><strong>2) 通过教学来强化学习并积累受众</strong></p><p><em>第二好的学习方式，就是把你所知道的、正在学的，以及为了实现盈利或有意义的目标而做过的事情，教给别人。</em></p><p>当你教别人东西时，你会挣扎……极度挣扎。</p><p>人们在教学中挣扎时就会开始想：“我还不够好。”</p><p>没错，你确实不够好。其他人也一样。</p><p>在教学中挣扎是一个自我教育的机会，让你能用特定的信息来填补自己的知识空白。</p><p>在写内容时：</p><ul><li>传授你的技能</li><li>传授你的思维方式</li><li>尝试从你的视角理清复杂的概念</li><li>传授你两极分化的信念（比如“每个人都应该成为纯肉食者”）及其原因</li></ul><p>教学不仅能建立权威，还能将你变成一个价值创造者。</p><p>如果“价值”等同于积极的行为改变，那么大多数创作者都没有价值。</p><p>当你披着内容创作者的外衣开办一家<a href="/letters/why-micro-education-businesses-are-the-future-zero-dollars-to-start">微型教育企业</a>时，你就为自己的超高利润打下了基础。</p><p><strong>3) 用你学到的知识去帮助别人以赚取收入</strong></p><p>到这个时候，假设你已经建立了一个有价值的、拥有五千到一万粉丝的社交媒体账号。</p><p>你已经完全有资格凭借你的技能收费去帮助他人了。</p><p>大多数人都没有这样的成果。</p><p>我说的不仅仅是涨粉。我指的是促成这个结果的一切过程。</p><p>假设你已经学会了：</p><ul><li>内容写作</li><li>长文（Thread）写作</li><li>个人主页设计</li><li>邮件订阅页</li><li>时事通讯写作</li></ul><p>就在过去的一周里，我亲眼看到有人通过出售关于如何创建 X（推特）长推文的咨询和课程来赚钱（而且相对于他们的账号规模，他们赚得真不少）。</p><p>在这个阶段，从小处着手。</p><p>不要试图搞出什么疯狂的报价（offer），一上来就收个一两万美元。</p><p>弄清楚你在哪个领域变得最擅长，别把它想得太复杂。</p><p>如果你在长文或长帖上取得了成果——那就围绕它创造产品或服务。</p><p>如果你擅长主页和内容设计——那就围绕它创造产品或服务。</p><p>如果你的生产力系统让你的专注力爆表——那就围绕它创造产品或服务。</p><p><em>如果你做到了，并且它帮助了你的生意，那就意味着它可以帮助其他在这个领域挣扎的人。</em></p><p><em>解决你自己的问题，并把这个解决方案卖出去。</em></p><p>这时你就要开始疯狂吸收有关文案、营销和销售的知识了。</p><p>这些技能只会不断增强你的销售能力。</p><p>但你要意识到，获取技能实际上就是获取技巧。</p><p>你在社交媒体上变得更强，是靠不断试验长文写作、帖子结构、智囊团（mastermind groups）等技巧，直到你学会如何拿到结果。</p><p>现在，去卖<em>技巧</em>，而不是卖技能。</p><p><strong>3.5) 另一条同样可行的路线</strong></p><p>商业和营销类的产品及服务很好卖。</p><p>它们对新手非常友好。</p><p>而且不管你卖什么，最终你都会需要这些技能。</p><p>所以，如果你刚踏入社会，没有任何其他技能或兴趣，那就照我刚才在第3步里告诉你的去做。</p><p>你可以（而且应该）至少每季度（3个月）创建并推出一个产品或服务来销售，持续2到3年。</p><p>别对这话不以为然。</p><p>是的，任务量很大。</p><p>但这就是我与那些做着同样时长的这件事，却只赚到我十分之一收入的人之间，我所能看到的唯一且最准确的区别。</p><p>构建（做产品）会逼着你去进化和学习。</p><p>创造一个新产品不仅仅是创造一个新产品。</p><p>它是用你为了构建产品、销售产品和改进产品所必须掌握的技能与心态，去创造一个全新的自我身份。</p><p>商业成长是个人成长的载体。</p><p>你可以走的另一条路线，是创造一个<em>你</em>自己会买、会用并从中获益的产品或服务。</p><p>一个大多数人一带而过的商业原则是“卖已经在畅销的东西”。</p><p>你先不要试图去创造新市场。</p><p>把手伸进那些已经在流动的市场中。</p><p>你最近买了什么产品？</p><p>你每天在用哪些？</p><p>你上过哪些课并从中拿到了自己的结果？</p><p>当我刚在社交媒体上起步时，我创造并销售了一款网页设计和自由职业的产品。</p><p>为什么？<em>因为我自己就买了 5 到 10 个网页设计和自由职业的课程。</em></p><p>我知道它们卖得出去。我并没有去信“市场已经饱和”这种愚蠢的论调。</p><p>而且，我在自由职业方面也拿到了结果。</p><p>随着我的成长，我创造了力量规划手帐（Power Planner）。</p><p>为什么？因为我一直在用规划手帐，却总是希望里面能增加点别的东西。</p><p>我也很喜欢在我的内容中谈论生产力。</p><p>我在<a href="/letters/the-best-online-business-model-to-make-1-million-in-2023">2023年赚取100万美元的最佳在线生意</a>中详细拆解了如何创建一个最小可行性报价（产品或服务）。</p><p><strong>4) 利用你的成果和受众赚取更多收入</strong></p><p>好了，我们现在扯得有点发散了。</p><p>到了这一步，你已经拥有了：</p><ul><li>高价值的技能栈（解决有利可图的问题的能力）</li><li>不断增长的受众或读者群（有着有利可图的问题的人）</li><li>构建和销售的经验（更擅长解决有利可图的问题）</li></ul><p>在这场数字复兴中，你正处于所能处在的最优位置之一。</p><p>你拥有资源成为一个独立的思考者和赚钱者。</p><p>你不必屈从于你讨厌的政府议程。</p><p>你也不必向分配给你工作的人汇报。</p><p>站在这个拥有全新经验的位置上，你需要把你的成果产品化。</p><p>如果你曾通过自由职业或咨询帮助过别人：</p><ul><li>写下让你取得成果的<em>确切步骤</em>。</li><li>如果你还没有步骤，现在就建构出来，并在过程中不断完善。</li><li>这些步骤就是你的独特机制。这是你的营销方式，即营销一个能解决某人生活中问题并帮他们达到期望结果的解决方案。</li><li>写下他们生活中期望的结果（他们对未来的愿景是什么？）你卖的是更美好的生活。</li><li>写下他们生活中最坏的结果（他们对未来的反向愿景是什么？）你在帮助他们避免痛苦。</li></ul><p>这就是你的营销策略。</p><p>在你的着陆页上，首先详细写出他们的反向愿景。</p><p>然后，谈谈他们能够实现的愿景。</p><p>最后，亮出你的解决方案，以此作为弥合差距的桥梁。</p><p>模仿其他着陆页，去理解标题和内容结构，并将其作为你打造第一个着陆页的辅助轮。</p><p>随着你读者群体的增长，继续把精力集中在客户服务这种低杠杆活动上是毫无意义的。</p><p>如果你还不打算立刻雇佣团队并投身于管理——那么合乎逻辑的选择就是，去打造一款只需极少精力且拥有高利润率的数字产品。</p><p>这就是一些一人企业创业者赚取数百万美元的方法。</p><p>他们明白，如果能获得 1 个粉丝，就能获得 100 万个粉丝。</p><p>而且，如果他们拥有一款无需耗费人力去交付的产品，他们就能把这 100 万双关注的眼睛转化为数百万美元。</p><p>希望你喜欢这篇文章。</p><p>下周见，</p><p>Dan</p><hr><p><a href="/en/letters/how-smart-creators-make-money-the-build-teach-earn-method">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',262))])}const y=o(d,[["render",c]]);export{q as __pageData,y as default};
